import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Home from './pages/Home/Home';
import Menu from './pages/Menu/Menu';
// Giả sử bạn tạo file LoadingScreen ở thư mục components
import LoadingScreen from './components/LoadingScreen'; 

function App() {
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Cho nó load khoảng 3 giây cho oai, hoặc đợi data từ model burnout
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  // Nếu đang loading thì hiện trang Equilibrium
  if (loading) {
    return <LoadingScreen />;
  }

  // Hết loading thì hiện Router như bình thường
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/menu" element={<Menu />} />
      </Routes>
    </Router>
  );
}

export default App;
